<?php require_once 'config.php'; if(isset($_SESSION['user_id'])) go_home(); $error='';$ok=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']);$email=trim($_POST['email']);$mobile=trim($_POST['mobile']);$age=(int)$_POST['age'];$pass=$_POST['password']; $hash=password_hash($pass,PASSWORD_DEFAULT); $q=mysqli_prepare($conn,'INSERT INTO users(name,email,mobile,age,password,role) VALUES(?,?,?,?,?,"user")'); mysqli_stmt_bind_param($q,'sssis',$name,$email,$mobile,$age,$hash); if(mysqli_stmt_execute($q)) $ok='Registration successful. You can login now.'; else $error='Email already exists.'; }
?><!doctype html><html><head><title>Register</title><link rel="stylesheet" href="assets/css/root/register.css"></head><body><div class="box"><h1>📝 Register</h1><?php if($error): ?><div class="error"><?=e($error)?></div><?php endif;?><?php if($ok): ?><div class="success"><?=e($ok)?></div><a href="index.php">Login</a><?php else:?><form method="post"><input name="name" placeholder="Full Name" required><input type="email" name="email" placeholder="Email" required><input name="mobile" placeholder="Mobile"><input type="number" name="age" placeholder="Age"><input type="password" name="password" placeholder="Password" required><button>Register</button></form><?php endif;?></div></body></html>
